-- Coupa -> canonical PO_LINE (COUPA). Generated by tools/build_silver_sql.py.
WITH l AS (SELECT p.RAW AS P, f.value AS L FROM {{ source('src_coupa', 'coupa_purchase_orders') }} p, LATERAL FLATTEN(p.RAW:"order-lines") f)
SELECT 'COUPA' AS SOURCE_SLOT, 'Coupa' AS SOURCE_SYSTEM, SPLIT_PART(l.P:account.code::STRING, '-', 1) AS COMPANY_CODE, o.PLANT, l.P:"po-number"::STRING AS PO_NUMBER,
  l.L:"line-num"::STRING AS PO_ITEM, l.P:supplier.id::STRING AS SUPPLIER_ID, NULL::STRING AS MATERIAL,
  l.L:description::STRING AS ITEM_TEXT, g.MATERIAL_GROUP, l.L:quantity::FLOAT AS QUANTITY, l.L:uom.code::STRING AS UOM,
  l.L:price::FLOAT AS NET_PRICE, l.L:total::FLOAT AS NET_VALUE, l.P:currency.code::STRING AS CURRENCY,
  l.P:"created-at"::TIMESTAMP::DATE AS PO_DATE, NULL::DATE AS DELIVERY_DATE, NULL::STRING AS CONTRACT_ID
FROM l LEFT JOIN {{ source('src_third_party', 'ref_material_group') }} g ON g.MATERIAL_GROUP_TEXT = l.L:commodity.name::STRING
LEFT JOIN (SELECT COMPANY_CODE, MIN(PLANT) AS PLANT FROM {{ source('src_third_party', 'ref_org') }} GROUP BY 1) o ON o.COMPANY_CODE = SPLIT_PART(l.P:account.code::STRING, '-', 1)
